<fieldset class="envasado-material"><legend>Material físico</legend>
<label>Insumo<select required class="form-control" name="materiales[{{ $indice }}][insumo_id]"><option value="">Selecciona un insumo</option>@foreach($insumos as $insumo)<option value="{{ $insumo->id }}" @selected($material?->insumo_id === $insumo->id)>{{ $insumo->nombre }} ({{ $insumo->unidad_medida }})</option>@endforeach</select></label>
<label>Función<select class="form-control" name="materiales[{{ $indice }}][funcion]">@foreach(['envase'=>'Envase vacío','etiqueta'=>'Etiqueta','contratapa'=>'Contratapa','tapa'=>'Tapa normal (control confirmado)','manga'=>'Manga termocontraíble','otro_fisico'=>'Otro material físico'] as $clave=>$texto)<option value="{{ $clave }}" @selected($material?->funcion === $clave)>{{ $texto }}</option>@endforeach</select></label>
<label>Base de consumo<select class="form-control" name="materiales[{{ $indice }}][base_consumo]"><option value="unidad">Por unidad envasada</option><option value="empaque" @selected($material?->base_consumo === 'empaque')>Por empaque (sin descuento automático)</option></select></label>
<label>Cantidad por unidad o empaque<input class="form-control" required type="number" min="0.001" max="1000000" step="0.001" name="materiales[{{ $indice }}][cantidad_por_unidad]" value="{{ $material?->cantidad_por_unidad }}"></label>
<label>Tipo de empaque (solo base empaque)<input class="form-control" maxlength="50" name="materiales[{{ $indice }}][tipo_empaque]" value="{{ $material?->tipo_empaque }}"></label>
<label>Unidades del empaque (solo base empaque)<input class="form-control" type="number" min="2" max="1000" name="materiales[{{ $indice }}][unidades_por_empaque]" value="{{ $material && $material->unidades_por_empaque ? $material->unidades_por_empaque : '' }}"></label>
<button class="btn btn-secondary" type="button" data-retirar-material>Retirar material</button></fieldset>
